UPDATE exercise_definitions SET instructions = ARRAY['Sit down on the Shoulder Press Machine and select the weight.', 'Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.', 'Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.', 'Lower the handles slowly back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Machine_Shoulder_Military_Press' WHERE lower(name) = lower('Machine Shoulder Press') AND owner_id IS NULL;
