UPDATE exercise_definitions SET instructions = ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.', 'Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Sit-Up' WHERE lower(name) = lower('Sit-Up') AND owner_id IS NULL;
