UPDATE exercise_definitions SET instructions = ARRAY['Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out.', 'Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent.', 'Reverse the motion by extending the elbow, pushing yourself back up into the starting position.', 'Repeat for the desired number of repetitions.']::text[], image_key = 'Parallel_Bar_Dip' WHERE lower(name) = lower('Parallel Bar Dip') AND owner_id IS NULL;
