UPDATE exercise_definitions SET instructions = ARRAY['There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements.', 'After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up.', 'Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.']::text[], image_key = 'Farmers_Walk' WHERE lower(name) = lower('Farmer''s Walk') AND owner_id IS NULL;
