UPDATE exercise_definitions SET instructions = ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], image_key = 'Lying_Leg_Curls' WHERE lower(name) = lower('Lying Leg Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Lying Leg Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad.', 'Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.', 'Return to the starting position, keeping your descent under control.']::text[], image_key = 'Glute_Ham_Raise' WHERE lower(name) = lower('Glute-Ham Raise') AND owner_id IS NULL;
