UPDATE exercise_definitions SET instructions = ARRAY['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Seated_Calf_Raise' WHERE lower(name) = lower('Seated Calf Raise') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Seated Calf Raise') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position.', 'Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same until the bar passes the knees.', 'Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body. At peak extension, shrug the shoulders and allow the elbows to flex to the side.', 'As you move your feet into the receiving position, a slightly wider position, pull yourself below the bar as you elevate the bar overhead. The bar should be received in a partial squat. Continue raising the bar to the overhead position, receiving the bar locked out overhead.', 'Return to a standing position with the weight over head.']::text[], image_key = 'Power_Snatch' WHERE lower(name) = lower('Power Snatch') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Power Snatch') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.', 'Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.', 'Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.', 'Pause at the end of the motion before returning the handles to the start position.']::text[], image_key = 'Cable_Rear_Delt_Fly' WHERE lower(name) = lower('Cable Rear Delt Fly') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Cable Rear Delt Fly') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks.', 'Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.', 'Press the bar back up as fast as you can, keeping the bar, your wrists, and elbows in line as you do so.']::text[], image_key = 'Floor_Press' WHERE lower(name) = lower('Floor Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Floor Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin lying on your back with your hands extended above you toward the ceiling.', 'Bring your feet, knees, and hips up to 90 degrees.', 'Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.', 'Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.', 'Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.', 'Stay tight and return the working leg to the starting position.', 'Repeat on the opposite side, alternating until the set is complete.']::text[], image_key = 'Dead_Bug' WHERE lower(name) = lower('Dead Bug') AND owner_id IS NULL;
