UPDATE exercise_definitions SET instructions = ARRAY['Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.', 'With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.', 'Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.', 'Hold the repetition for several seconds before returning to the starting position.', 'At the conclusion of the set, repeat facing the other direction.']::text[], image_key = 'Pallof_Press' WHERE lower(name) = lower('Pallof Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Pallof Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.', 'Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.', 'Push body up until arms are extended. Repeat.']::text[], image_key = 'Incline_Push-Up' WHERE lower(name) = lower('Incline Push-Up') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Incline Push-Up') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away.', 'Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley.', 'Now step out and away from the stack with a wide stance and grasp the bar of the pulley system.', 'Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position.', 'Now perform the movement by moving the leg with the ankle cuff in front of the far leg by using the inner thighs to abduct the hip. Breathe out during this portion of the movement.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and then repeat the same movement with the opposite leg.']::text[], image_key = 'Cable_Hip_Adduction' WHERE lower(name) = lower('Cable Hip Adduction') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Cable Hip Adduction') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Seat on a flat bench with your back facing a high pulley.', 'Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position.', 'With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step.', 'As you inhale, go back to the initial position slowly.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Cable_Seated_Crunch' WHERE lower(name) = lower('Cable Seated Crunch') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Cable Seated Crunch') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and step forward with your right leg and squat down through your hips, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: Do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. li>', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[], image_key = 'Barbell_Lunge' WHERE lower(name) = lower('Barbell Lunge') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Barbell Lunge') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Reverse_Cable_Curl' WHERE lower(name) = lower('Reverse Cable Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Reverse Cable Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward).', 'Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.', 'Lower the bar down to the shoulders slowly as you inhale.', 'Lift the bar back up to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Barbell_Shoulder_Press' WHERE lower(name) = lower('Barbell Overhead Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Barbell Overhead Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], image_key = 'Pullups' WHERE lower(name) = lower('Pull-Up') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Pull-Up') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit on the machine with your back flat on the pad.', 'Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.', 'Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.', 'Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Butterfly' WHERE lower(name) = lower('Pec Deck') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Pec Deck') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.', 'Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.', 'Pause at the completion of the movement, and then slowly return the weight to the starting position.', 'Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.']::text[], image_key = 'Machine_Triceps_Extension' WHERE lower(name) = lower('Machine Tricep Extension') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Machine Tricep Extension') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).', 'Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Barbell_Squat' WHERE lower(name) = lower('Barbell Back Squat') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'squat' WHERE lower(name) = lower('Barbell Back Squat') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand in front of a loaded barbell.', 'While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.', 'While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.', 'Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.', 'Perform the amount of repetitions prescribed in the program.']::text[], image_key = 'Barbell_Deadlift' WHERE lower(name) = lower('Conventional Deadlift') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Conventional Deadlift') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.', 'Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.', 'Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.', 'After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Triceps_Pushdown' WHERE lower(name) = lower('Tricep Pushdown') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Tricep Pushdown') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.', 'Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.', 'As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.']::text[], image_key = 'Lying_Leg_Curls' WHERE lower(name) = lower('Leg Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Leg Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Hack_Squat' WHERE lower(name) = lower('Hack Squat Machine') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'squat' WHERE lower(name) = lower('Hack Squat Machine') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Standing_Calf_Raises' WHERE lower(name) = lower('Standing Calf Raise') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Standing Calf Raise') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad.', 'Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Donkey_Calf_Raises' WHERE lower(name) = lower('Donkey Calf Raise') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Donkey Calf Raise') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Thigh_Abductor' WHERE lower(name) = lower('Hip Abductor Machine') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Hip Abductor Machine') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Thigh_Adductor' WHERE lower(name) = lower('Hip Adductor Machine') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Hip Adductor Machine') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.', 'As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.', 'Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.', 'Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded.']::text[], image_key = 'Leg_Press' WHERE lower(name) = lower('Leg Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Leg Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.']::text[], image_key = 'Face_Pull' WHERE lower(name) = lower('Face Pull') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Face Pull') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], image_key = 'Dumbbell_Bench_Press' WHERE lower(name) = lower('Dumbbell Bench Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Dumbbell Bench Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position.', 'To begin the movement, flex the hips, pulling the legs forward.', 'Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion.', 'Return by again flexing the hip, pulling the carriage forward as far as you can.', 'Repeat for the desired number of repetitions.']::text[], image_key = 'Reverse_Hyperextension' WHERE lower(name) = lower('Reverse Hyperextension') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Reverse Hyperextension') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[], image_key = 'Decline_Push-Up' WHERE lower(name) = lower('Decline Push-Up') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Decline Push-Up') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin in a standing position.', 'Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position.', 'Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion.', 'Pause at the top of the motion, and then slowly return to the starting position.']::text[], image_key = 'Svend_Press' WHERE lower(name) = lower('Svend Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Svend Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], image_key = 'Chin-Up' WHERE lower(name) = lower('Chin-Up') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Chin-Up') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[], image_key = 'Inverted_Row' WHERE lower(name) = lower('Inverted Row') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Inverted Row') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Choose a flat bench and place a dumbbell on each side of it.', 'Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.', 'Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.', 'Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.', 'Lower the resistance straight down to the starting position. Breathe in as you perform this step.', 'Repeat the movement for the specified amount of repetitions.', 'Switch sides and repeat again with the other arm.']::text[], image_key = 'One-Arm_Dumbbell_Row' WHERE lower(name) = lower('One-Arm Dumbbell Row') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('One-Arm Dumbbell Row') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.', 'Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.', 'While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.', 'While keeping the arms straight, go back to the starting position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Straight-Arm_Pulldown' WHERE lower(name) = lower('Straight-Arm Pulldown') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Straight-Arm Pulldown') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.', 'Lower your hips, look forward with your head and keep your chest up.', 'Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.', 'At the completion of the movement, lower the weight back to the ground under control.']::text[], image_key = 'Trap_Bar_Deadlift' WHERE lower(name) = lower('Trap Bar Deadlift') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Trap Bar Deadlift') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs.', 'Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.', 'Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position.', 'Now, exhale and push the dumbbells upward until they touch at the top.', 'Then, after a brief pause at the top contracted position, slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Dumbbell_Shoulder_Press' WHERE lower(name) = lower('Dumbbell Shoulder Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Dumbbell Shoulder Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.', 'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.', 'As you exhale, push the dumbbells up until they touch at the top.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Seated_Dumbbell_Press' WHERE lower(name) = lower('Seated Dumbbell Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Seated Dumbbell Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.', 'In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.', 'Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.', 'Pause at the rear of the movement, and slowly return the weight to the starting position.']::text[], image_key = 'Reverse_Machine_Flyes' WHERE lower(name) = lower('Reverse Pec Deck') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Reverse Pec Deck') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Dumbbell_Shrug' WHERE lower(name) = lower('Dumbbell Shrug') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Dumbbell Shrug') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Barbell_Shrug' WHERE lower(name) = lower('Barbell Shrug') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Barbell Shrug') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Barbell_Curl' WHERE lower(name) = lower('Barbell Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Barbell Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to the starting position as your breathe in. .', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Spider_Curl' WHERE lower(name) = lower('Spider Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Spider Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.']::text[], image_key = 'Single_Leg_Glute_Bridge' WHERE lower(name) = lower('Single-Leg Glute Bridge') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Single-Leg Glute Bridge') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders.', 'Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.', 'Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of the contraction. Your knees should remain extended. Hold the contracted position for a second before you start to go back down.', 'Return slowly to the starting position as you breathe in while lowering your heels.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Smith_Machine_Calf_Raise' WHERE lower(name) = lower('Smith Machine Calf Raise') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Smith Machine Calf Raise') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.', 'Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.', 'Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position.']::text[], image_key = 'Barbell_Hip_Thrust' WHERE lower(name) = lower('Barbell Hip Thrust') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Barbell Hip Thrust') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.']::text[], image_key = 'Hang_Clean' WHERE lower(name) = lower('Hang Clean') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Hang Clean') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.', 'Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions.']::text[], image_key = 'Cable_Crossover' WHERE lower(name) = lower('Cable Crossover') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Cable Crossover') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[], image_key = 'Cable_Chest_Press' WHERE lower(name) = lower('Cable Chest Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Cable Chest Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand.', 'Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position.', 'Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be perpendicular to the body at approximately shoulder level.', 'Return your arm back to the starting position by pulling your hand back to the midline of the body.', 'Hold for a second at the starting position and repeat the movement on the opposite side. Continue alternating back and forth for the prescribed number of repetitions.']::text[], image_key = 'Single-Arm_Cable_Crossover' WHERE lower(name) = lower('Single-Arm Cable Crossover') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Single-Arm Cable Crossover') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.']::text[], image_key = 'Cable_Shoulder_Press' WHERE lower(name) = lower('Cable Shoulder Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Cable Shoulder Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead.', 'Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position.', 'Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forearm is across your abs. You will be creating an imaginary semi-circle. Tip: The forearm should be perpendicular to your torso at all times.', 'Slowly go back to the initial position.', 'Repeat for the recommended amount of repetitions and then repeat the movement with the next arm.']::text[], image_key = 'Cable_Internal_Rotation' WHERE lower(name) = lower('Cable Internal Rotation') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Cable Internal Rotation') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[], image_key = 'Barbell_Glute_Bridge' WHERE lower(name) = lower('Barbell Glute Bridge') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Barbell Glute Bridge') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position.', 'Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead.', 'Lift the bar back to the starting position by extending the elbow and exhaling.', 'Repeat.']::text[], image_key = 'EZ-Bar_Skullcrusher' WHERE lower(name) = lower('EZ-Bar Skullcrusher') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('EZ-Bar Skullcrusher') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.', 'Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.', 'Pause at the bottom, and then bring the weight together at the top by extending through the elbows.']::text[], image_key = 'Dumbbell_Floor_Press' WHERE lower(name) = lower('Dumbbell Floor Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Dumbbell Floor Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin standing with a dumbbell in each hand with your feet shoulder width apart.', 'Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.', 'To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached.', 'After full extension, rebend the hips and knees to receive the weight in a squat position. Allow the arms to bend, guiding the dumbbells to your shoulders.', 'Upon receiving the weight in the squat position, extend the hips and knees to finish in a standing position with the weights on your shoulders.']::text[], image_key = 'Dumbbell_Clean' WHERE lower(name) = lower('Dumbbell Clean') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Dumbbell Clean') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[], image_key = 'Dumbbell_Side_Bend' WHERE lower(name) = lower('Dumbbell Side Bend') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Dumbbell Side Bend') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[], image_key = 'Dumbbell_Incline_Row' WHERE lower(name) = lower('Dumbbell Incline Row') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Dumbbell Incline Row') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], image_key = 'Wide-Grip_Lat_Pulldown' WHERE lower(name) = lower('Lat Pulldown') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Lat Pulldown') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit down on a pull-down machine with a V-Bar attached to the top pulley.', 'Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.', 'Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.', 'After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[], image_key = 'V-Bar_Pulldown' WHERE lower(name) = lower('V-Bar Pulldown') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('V-Bar Pulldown') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.', 'After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], image_key = 'Barbell_Bench_Press_-_Medium_Grip' WHERE lower(name) = lower('Barbell Bench Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Barbell Bench Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.', 'Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.', 'Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.', 'Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Romanian_Deadlift' WHERE lower(name) = lower('Romanian Deadlift') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Romanian Deadlift') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[], image_key = 'Sumo_Deadlift' WHERE lower(name) = lower('Sumo Deadlift') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Sumo Deadlift') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.', 'Lean over as you keep the natural alignment of your back and grab the V-bar handles.', 'With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.', 'Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Seated_Cable_Rows' WHERE lower(name) = lower('Seated Cable Row') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Seated Cable Row') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'As you breathe in, come down slowly until you feel the bar on your lower chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up).', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[], image_key = 'Decline_Barbell_Bench_Press' WHERE lower(name) = lower('Decline Barbell Bench Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Decline Barbell Bench Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, lock the bar back in the rack.']::text[], image_key = 'Smith_Machine_Bench_Press' WHERE lower(name) = lower('Smith Machine Bench Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Smith Machine Bench Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[], image_key = 'Good_Morning' WHERE lower(name) = lower('Good Morning') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Good Morning') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[], image_key = 'Deficit_Deadlift' WHERE lower(name) = lower('Deficit Deadlift') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'hinge' WHERE lower(name) = lower('Deficit Deadlift') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'EZ-Bar_Curl' WHERE lower(name) = lower('EZ-Bar Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('EZ-Bar Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Preacher_Curl' WHERE lower(name) = lower('Preacher Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Preacher Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[], image_key = 'Cross_Body_Hammer_Curl' WHERE lower(name) = lower('Cross-Body Hammer Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Cross-Body Hammer Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position.', 'Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.', 'As you exhale, press the bar back up by using the triceps to perform a close grip bench press.', 'Now go back to the starting position and start over.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'JM_Press' WHERE lower(name) = lower('JM Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('JM Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting position.', 'Keeping the upper arms stationary, slowly move the dumbbells in and down in a semi circular motion until they touch the upper chest while inhaling. Keep full control of the dumbbells at all times and do not move the upper arms nor rest the dumbbells on the chest.', 'As you breathe out, move the dumbbells up using your triceps and the same semi-circular motion but in reverse. Attempt to keep the dumbbells together as they move up. Lock your arms in the contracted position, hold for a second and then start coming down again slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[], image_key = 'Tate_Press' WHERE lower(name) = lower('Tate Press') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Tate Press') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side.', 'Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.', 'Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shoulder width apart from each other. Your body should be evenly aligned the handles. This is the starting position.', 'While exhaling, slowly squeeze the biceps on each side until your forearms and biceps touch.', 'While inhaling, move your forearms back to the starting position. Note: Your entire body is stationary during this exercise except for the forearms.', 'Repeat for the recommended amount of repetitions prescribed in your program.']::text[], image_key = 'Overhead_Cable_Curl' WHERE lower(name) = lower('Overhead Cable Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Overhead Cable Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired.', 'Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.', 'With your back, shoulders, and core tight, push your knees and butt out and you begin your descent. Sit back with your hips until you are seated on the box. Ideally, your shins should be perpendicular to the ground. Pause when you reach the box, and relax the hip flexors. Never bounce off of a box.', 'Keeping the weight on your heels and pushing your feet and knees out, drive upward off of the box as you lead the movement with your head. Continue upward, maintaining tightness head to toe.']::text[], image_key = 'Box_Squat' WHERE lower(name) = lower('Box Squat') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'squat' WHERE lower(name) = lower('Box Squat') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Seated_Leg_Curl' WHERE lower(name) = lower('Seated Leg Curl') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'isolation' WHERE lower(name) = lower('Seated Leg Curl') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.', 'Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.', 'Twist your torso to the right side until your arms are parallel with the floor while breathing out.', 'Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Russian_Twist' WHERE lower(name) = lower('Russian Twist') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Russian Twist') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly.', 'Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.', 'Place the bar about 1 inch in front of your shins and over the balls of your feet.', 'Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted.', 'Keep your head in a neutral position (in line with vertebral column and not tilted or rotated) with your eyes focused straight ahead. Inhale during this phase.', 'Lift the bar from the floor by forcefully extending the hips and the knees as you exhale. Tip: The upper torso should maintain the same angle. Do not bend at the waist yet and do not let the hips rise before the shoulders (this would have the effect of pushing the glutes in the air and stretching the hamstrings.', 'Keep elbows fully extended with the head in a neutral position and the shoulders over the bar.', 'As the bar raises keep it as close to the shins as possible.', 'As the bar passes the knees, thrust your hips forward and slightly bend the knees to avoid locking them. Tip: At this point your thighs should be against the bar.', 'Keep the back flat or slightly arched, elbows fully extended and your head neutral. Tip: You will hold your breath until the next phase.', 'Inhale and then forcefully and quickly extend your hips and knees and stand on your toes.', 'Keep the bar as close to your body as possible. Tip: Your back should be flat with the elbows pointed out to the sides and your head in a neutral position. Also, keep your shoulders over the bar and arms straight as long as possible.', 'When your lower body joints are fully extended, shrug the shoulders upward rapidly without letting the elbows flex yet. Exhale during this portion of the movement.', 'As the shoulders reach their highest elevation flex your elbows to begin pulling your body under the bar.', 'Continue to pull the arms as high and as long as possible. Tip: Due to the explosive nature of this phase, your torso will be erect or with an arched back, your head will be tilted back slightly and your feet may lose contact with the floor.', 'After the lower body has fully extended and the bar reaches near maximal height, pull your body under the bar and rotate the arms around and under the bar.', 'Simultaneously, flex the hips and knees into a quarter squat position.', 'Once the arms are under the bar, inhale and then lift your elbows to position the upper arms parallel to the floor. Rack the bar across the front of your collar bones and front shoulder muscles.', 'Catch the bar with an erect and tight torso, a neutral head position and flat feet. Exhale during this movement.', 'Stand up by extending the hips and knees to a fully erect position.', 'Lower the bar by gradually reducing the muscular tension of the arms to allow a controlled descent of the bar to the thighs. Inhale during this movement.', 'Simultaneously flex the hips and knees to cushion the impact of the bar on the thighs.', 'Squat down with the elbows fully extended until the bar touches the floor.', 'Start over at Phase 1 and repeat for the recommended amount of repetitions.']::text[], image_key = 'Power_Clean' WHERE lower(name) = lower('Power Clean') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Power Clean') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.', 'Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.', 'Next comes the second pull, the main source of acceleration for the clean. As the bar approaches the mid-thigh position, begin extending through the hips. In a jumping motion, accelerate by extending the hips, knees, and ankles, using speed to move the bar upward. There should be no need to actively pull through the arms to accelerate the weight; at the end of the second pull, the body should be fully extended, leaning slightly back, with the arms still extended.', 'As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, rotating your elbows under the bar as you do so. Receive the bar in a front squat position, the depth of which is dependent upon the height of the bar at the end of the third pull. The bar should be racked onto the protracted shoulders, lightly touching the throat with the hands relaxed. Continue to descend to the bottom squat position, which will help in the recovery.', 'Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.', 'The second phase is the jerk, which raises the weight overhead. Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible.', 'Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders.', 'At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as possible. In the brief moment the feet are not actively driving against the platform, the athletes effort to push the bar up will drive them down. The feet should be split, with one foot forward, and one foot back. Receive the bar with the arms locked out overhead. Return to a standing position.']::text[], image_key = 'Clean_and_Jerk' WHERE lower(name) = lower('Clean and Jerk') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'push' WHERE lower(name) = lower('Clean and Jerk') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other.', 'Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest.', 'Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all times and also maintain a straight back. Retract your shoulder blades. This is your starting position.', 'Slowly lower the weight by bending your knees until your thighs are parallel to the ground while inhaling. Tip: Keep your back straight while performing this exercise to avoid any injuries and your arms should remain extended and over your head at all times.', 'Now use your feet and legs to help bring the weight back up to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Overhead_Squat' WHERE lower(name) = lower('Overhead Squat') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'squat' WHERE lower(name) = lower('Overhead Squat') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip.', 'Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.', 'While keeping the upper arms perpendicular to the torso, pull the barbell up towards your upper chest as you squeeze the rear delts and you breathe out. Tip: When performed correctly, this exercise should resemble a bench press in reverse. Also, refrain from using your biceps to do the work. Focus on targeting the rear delts; the arms should only act as hooks.', 'Slowly go back to the initial position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[], image_key = 'Barbell_Rear_Delt_Row' WHERE lower(name) = lower('Barbell Rear Delt Row') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Barbell Rear Delt Row') AND owner_id IS NULL AND movement_pattern = '';
UPDATE exercise_definitions SET instructions = ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.', 'After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[], image_key = 'Wide-Grip_Lat_Pulldown' WHERE lower(name) = lower('Wide-Grip Lat Pulldown') AND owner_id IS NULL;
UPDATE exercise_definitions SET movement_pattern = 'pull' WHERE lower(name) = lower('Wide-Grip Lat Pulldown') AND owner_id IS NULL AND movement_pattern = '';

